CREATE TABLE stores (id text PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id text PRIMARY KEY, email text UNIQUE, phone text UNIQUE, name text, avatar_url text, preferred_language text, sizes jsonb NOT NULL DEFAULT '[]', style_preferences jsonb NOT NULL DEFAULT '[]', favorite_categories jsonb NOT NULL DEFAULT '[]', favorite_colors jsonb NOT NULL DEFAULT '[]', budget_preference integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id text PRIMARY KEY, store_id text NOT NULL REFERENCES stores(id), name text NOT NULL, description text NOT NULL, category text NOT NULL, subcategory text, brand text NOT NULL, price_amount integer NOT NULL CHECK (price_amount >= 0), currency text NOT NULL, colors jsonb NOT NULL, sizes jsonb NOT NULL, images jsonb NOT NULL, tags jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_variants (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), sku text UNIQUE NOT NULL, color jsonb NOT NULL, size jsonb NOT NULL, price_amount integer NOT NULL CHECK (price_amount >= 0), currency text NOT NULL, stock integer NOT NULL CHECK (stock >= 0));
CREATE TABLE favorites (user_id text NOT NULL REFERENCES users(id), product_id text NOT NULL REFERENCES products(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, product_id));
CREATE TABLE carts (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), store_id text NOT NULL REFERENCES stores(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cart_items (id text PRIMARY KEY, cart_id text NOT NULL REFERENCES carts(id), variant_id text NOT NULL REFERENCES product_variants(id), quantity integer NOT NULL CHECK (quantity > 0));
CREATE TABLE reservations (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), store_id text NOT NULL REFERENCES stores(id), variant_id text NOT NULL REFERENCES product_variants(id), quantity integer NOT NULL CHECK (quantity > 0), status text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations (id text PRIMARY KEY, user_id text REFERENCES users(id), guest_id text, store_id text REFERENCES stores(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id text PRIMARY KEY, conversation_id text NOT NULL REFERENCES conversations(id), role text NOT NULL, type text NOT NULL, content text NOT NULL, product_ids jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consultant_handoffs (id text PRIMARY KEY, conversation_id text NOT NULL REFERENCES conversations(id), user_id text REFERENCES users(id), selected_product_ids jsonb NOT NULL, requested_sizes jsonb NOT NULL, preferences jsonb NOT NULL, summary text NOT NULL, reason text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), store_id text NOT NULL REFERENCES stores(id), status text NOT NULL, subtotal_amount integer NOT NULL CHECK (subtotal_amount >= 0), currency text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_items (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), variant_id text NOT NULL REFERENCES product_variants(id), quantity integer NOT NULL CHECK (quantity > 0), unit_price_amount integer NOT NULL CHECK (unit_price_amount >= 0));
